import{_ as l,l as s,o as e,c as i,v as t,p as n,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"TLS 攻击史","description":"","frontmatter":{"title":"TLS 攻击史","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tls-attack-history.md","filePath":"cs/tls-attack-history.md","lastUpdated":1789023840000}'),p={name:"cs/tls-attack-history.md"};function E(A,a,S,_,u,T){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="tls-攻击史" tabindex="-1">TLS 攻击史 <a class="header-anchor" href="#tls-攻击史" aria-label="Permalink to &quot;TLS 攻击史&quot;">​</a></h1><div class="epigraph"><p>TLS 的历史是合同一次次被实现与降级打穿：明文恢复、填充预言、导出密钥、版本回退。TLS 1.3 删掉的东西，多半是这份名单教过的。</p><footer>—— 据 RFC 8446 的设计动机；Rescorla, *The Transport Layer Security Protocol*；对照 Vaudenay 与 BEAST/Lucky Thirteen 的公开分析</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/acme">ACME</a>让证书常见。缺口是<strong>记录层与握手曾怎样失败</strong>。主干<a href="/cs/tls-handshake">TLS 握手</a>已有 1.2/1.3 形状。本课用历史当反例清单：降级、可区分错误、压缩、重协商——不给复现步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>证书对了，记录层仍可能用 CBC+MAC、导出、压缩。攻击史说明：主动敌手改握手选弱套件；计时区分填充；压缩与密钥同流。TLS 1.3：只 AEAD、HKDF、去掉重协商与压缩。缺口是「为何删」，不是再背扩展号。</p><h3 id="降级是协议漏洞" tabindex="-1">降级是协议漏洞 <a class="header-anchor" href="#降级是协议漏洞" aria-label="Permalink to &quot;降级是协议漏洞&quot;">​</a></h3><p>回退到 SSL 3.0 或出口套件不是用户偏好，是敌手可选的模式。版本与套件必须认证绑定。</p><p><span class="marginnote">RFC 8446 引言即针对旧缺陷。POODLE、BEAST、CRIME、Heartbleed 作为失败模式点名：实现越界读也算史。本课禁止操作指导。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按层分类：握手绑定、记录完整性、压缩、实现内存。每类对应 1.3 的一条删除或加固。指出中间盒终止 TLS 会重开这些选择。</p>',12)),(e(),n(c,null,{default:r(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E5%A5%97%E4%BB%B6%E4%B8%8E%E9%99%8D%E7%BA%A7%22%5D%20--%3E%20DROP%5B%22TLS%201.3%20%E5%88%A0%E9%99%A4%22%5D%0A%20%20PAD%5B%22%E5%8F%AF%E5%8C%BA%E5%88%86%E5%A1%AB%E5%85%85%22%5D%20--%3E%20DROP%0A%20%20COMP%5B%22%E5%8E%8B%E7%BC%A9%E4%B8%8E%E9%87%8D%E5%8D%8F%E5%95%86%22%5D%20--%3E%20DROP%0A%20%20DROP%20--%3E%20AEAD%5B%22%E5%8F%AA%E7%95%99%20AEAD%20%2B%20HKDF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>协议安全是版本化的合同。部署「兼容一切」等于把最弱环留给主动者。后课 SSH/IPsec/WireGuard 是另一些合同，不要假设「已有 TLS」覆盖它们的威胁模型。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分析某一 CVE 的报文。SSH 下一课：主机钥与用户钥，另一条远程管理信道。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>证书自动化之后，记录层历史说明要删弱合同。</li><li>降级、填充预言、压缩是主动敌手的经典通道。</li><li>1.3 的缩小表面是设计结论，不是审美。</li><li>下一课 SSH 密钥认证。</li><li>出处：RFC 8446；Rescorla；Vaudenay, 2002；对照 Anderson。</li></ul>',8))])}const f=l(p,[["render",E]]);export{D as __pageData,f as default};
